-- P99-reviewed Velious content. Quest faction gates deliberately bypassed; actual faction rewards retained.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("Just another boring day waiting for supplies.  I wonder when they will arrive.")
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 25106 }) then
    e.self:Say("Well, well, I see Wenglawks finally got around to sending me my new spear. I hope it's not as shoddy as the last one. Your payment? Bahaha, did Wenglawks not tell you? Payment was to be a giant icewurm tooth carved into an amulet. Come now, little one. I will find an ice wurm for us to slay together. Then you can pull one of its teeth out for me and I will fashion the talisman for that greedy merchant.")
    eq.spawn2(118164, 0, 0, -2589, -4083, 136, 131)
  elseif item_lib.check_turn_in(e.trade, { item1 = 25191 }) then
    e.self:Emote("pulls out a large knife and begins to carve at the tooth. After a few minutes he pulls out a length of rope and fashions it into a very large necklace. 'Here is his payment. Tell him the spear is fine, and that I might reconsider his last offer to me. He will know what I mean.'")
    e.other:SummonItem(25130)
  elseif item_lib.check_turn_in(e.trade, { item1 = 25266 }) then
    e.self:Say("Supplies from Svekk?  Where are the rest of them little one!  There must be more, we are here pushing the Coldain back into their hole in the wall and Svekk sends a " .. e.other:GetRaceName() .. " to deliver a small portion of supplies.  Take this note back to that fool.  Leave quickly before I take my rage out upon you.")
    e.other:Faction(448, 10, 0)
    e.other:Faction(419, 10, 0)
    e.other:Faction(406, -30, 0)
    e.other:Faction(430, -30, 0)
    e.other:AddEXP(250)
    e.other:SummonItem(25267)
  elseif item_lib.check_turn_in(e.trade, { item1 = 25269 }) then
    e.self:Say("I am in your debt, " .. e.other:GetRaceName() .. ".  These supplies will help our effort to destroy the Coldain.  I wish I had more to give than what I do.'  Bekerak pulls a strange looking totem on a string from one of his pockets and hands it to you.  'May Lord Rallos smile upon you, " .. e.other:GetCleanName() .. ".'")
    e.other:Faction(448, 10, 0)
    e.other:Faction(419, 10, 0)
    e.other:Faction(406, -30, 0)
    e.other:Faction(430, -30, 0)
    e.other:AddEXP(250)
    e.other:SummonItem(25268)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
